package com.aistock.market.marketrefs;
import com.aistock.common.marketrefs.*;import com.aistock.common.marketrefs.MarketReferenceRecords.OwnerResult;import com.fasterxml.jackson.databind.*;import com.fasterxml.jackson.core.JsonParser;import java.io.*;import java.net.*;import java.net.http.*;import java.nio.ByteBuffer;import java.time.*;import java.util.*;import java.util.concurrent.*;import org.springframework.beans.factory.annotation.*;import org.springframework.stereotype.Component;
@Component public class MarketVersionReferenceClient {
 private final Map<String,URI> urls;private final String token;private final ObjectMapper mapper;private final Duration timeout;
 private final HttpClient client=HttpClient.newBuilder().connectTimeout(Duration.ofSeconds(1)).followRedirects(HttpClient.Redirect.NEVER).build();
 @Autowired public MarketVersionReferenceClient(@Value("${aistock.references.prediction-url:http://127.0.0.1:18083}")String prediction,@Value("${aistock.references.scheduler-url:http://127.0.0.1:18084}")String scheduler,@Value("${aistock.references.notification-url:http://127.0.0.1:18085}")String notification,@Value("${aistock.internal.token:}")String token,ObjectMapper mapper){this(Map.of("prediction",prediction,"scheduler",scheduler,"notification",notification),token,mapper,Duration.ofSeconds(4));}
 MarketVersionReferenceClient(Map<String,String> urls,String token,ObjectMapper mapper,Duration timeout){if(!urls.keySet().equals(MarketReferenceInput.OWNERS)||timeout.isZero()||timeout.isNegative()||timeout.compareTo(Duration.ofSeconds(4))>0)throw new IllegalArgumentException("Invalid reference client settings");var normalized=new LinkedHashMap<String,URI>();urls.forEach((owner,text)->{URI uri=URI.create(text);if(!Set.of("http","https").contains(uri.getScheme())||uri.getHost()==null||uri.getUserInfo()!=null||uri.getQuery()!=null||uri.getFragment()!=null||uri.getPath()!=null&&!Set.of("","/").contains(uri.getPath()))throw new IllegalArgumentException("Invalid internal reference URL");normalized.put(owner,uri);});this.urls=Map.copyOf(normalized);this.token=token;this.mapper=mapper.copy().enable(JsonParser.Feature.STRICT_DUPLICATE_DETECTION).enable(DeserializationFeature.FAIL_ON_TRAILING_TOKENS);this.timeout=timeout;}
 public OwnerResult read(String owner,String version){MarketReferenceInput.requireVersion(version);if(!urls.containsKey(owner))throw new IllegalArgumentException("Unknown owner");if(token==null||token.isBlank())return unknown(owner,version,"REFERENCE_SERVICE_UNAVAILABLE");CompletableFuture<HttpResponse<byte[]>> pending=null;var body=new LimitedBody();
  try{var request=HttpRequest.newBuilder(urls.get(owner).resolve(MarketReferenceInput.INTERNAL_BASE+"/"+version)).timeout(timeout).header("X-Service-Token",token).header("Accept","application/json").GET().build();pending=client.sendAsync(request,info->body);var response=pending.get(timeout.toMillis(),TimeUnit.MILLISECONDS);if(response.statusCode()!=200)return unknown(owner,version,"REFERENCE_SERVICE_UNAVAILABLE");
   try{var root=mapper.readTree(response.body());if(root==null||!root.isObject()||!"OK".equals(root.path("code").asText())||!root.path("data").isObject())return unknown(owner,version,"REFERENCE_RESPONSE_INVALID");return MarketReferenceInput.decodeOwner(mapper.writeValueAsBytes(root.get("data")),owner,version);}catch(IOException|RuntimeException e){return unknown(owner,version,"REFERENCE_RESPONSE_INVALID");}
  }catch(InterruptedException e){Thread.currentThread().interrupt();return unknown(owner,version,"REFERENCE_SERVICE_UNAVAILABLE");}catch(ExecutionException|TimeoutException|RuntimeException e){return unknown(owner,version,"REFERENCE_SERVICE_UNAVAILABLE");}finally{body.cancel();if(pending!=null)pending.cancel(true);}
 }
 private OwnerResult unknown(String owner,String version,String reason){return new OwnerResult(owner,version,Instant.now(),"UNKNOWN",reason,List.of());}
 private static final class LimitedBody implements HttpResponse.BodySubscriber<byte[]> {
  private final ByteArrayOutputStream out=new ByteArrayOutputStream();private final CompletableFuture<byte[]> body=new CompletableFuture<>();private volatile Flow.Subscription subscription;
  public CompletionStage<byte[]> getBody(){return body;}
  public void onSubscribe(Flow.Subscription s){subscription=s;s.request(1);}
  public void onNext(List<ByteBuffer> chunks){for(var chunk:chunks){if(chunk.remaining()>65536-out.size()){subscription.cancel();body.completeExceptionally(new IOException("Reference response limit"));return;}byte[] part=new byte[chunk.remaining()];chunk.get(part);out.writeBytes(part);}subscription.request(1);}
  public void onError(Throwable e){body.completeExceptionally(e);}public void onComplete(){body.complete(out.toByteArray());}
  void cancel(){var s=subscription;if(s!=null)s.cancel();body.cancel(true);}
 }
}
